@rendermode InteractiveServer

@using NotificationsApp.Services
@inject NotificationService Svc
@inject PersistentComponentState PersistentState
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span style="background:#0d6efd;color:#fff;border-radius:50%;padding:2px 10px;font-size:0.6em;vertical-align:middle;">
        @_notifications.Count
    </span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul>
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li>
                <strong>@n.Timestamp.ToString("T")</strong> &mdash; @n.Message
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = [];
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription? _persistSub;

    protected override void OnInitialized()
    {
        // During SSR: load from service and register a callback to persist
        // the data into the page so the interactive runtime can pick it up.
        // During interactive: restore the persisted data instead of re-fetching.
        if (!PersistentState.TryTakeFromJson<List<Notification>>(
                "notifications", out var restored))
        {
            // SSR path — fetch once, register persistence callback.
            _notifications = Svc.GetAll();
            _persistSub = PersistentState.RegisterOnPersisting(() =>
            {
                PersistentState.PersistAsJson("notifications", _notifications);
                return Task.CompletedTask;
            });
        }
        else
        {
            // Interactive path — use the data that was already rendered.
            _notifications = restored!;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender && RendererInfo.IsInteractive)
        {
            // The page is now live in the browser — safe to start polling.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Track the highest Id we already have so we only fetch new ones.
        var lastSeenId = _notifications.Count > 0
            ? _notifications.Max(n => n.Id)
            : 0;

        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            // Simulate some external system creating notifications.
            Svc.SimulateExternalActivity();

            var newer = Svc.GetSince(lastSeenId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub?.Dispose();

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

